export async function protectedManifest(phase){
 const target=join(EVIDENCE,`workload-protected.${phase}.json`);
 if(phase==='before'&&await exists(target)){const prior=await readJson(target);if(prior.provenance?.immutable===true)return prior;}
 const files=[];for(const root of PROTECTED_ROOTS){const absolute=join(PLATFORM,root);for(const path of await walk(absolute)){const info=await stat(path);const body=await readFile(path);files.push({path:relative(PLATFORM,path),mode:(info.mode&0o777).toString(8),bytes:body.length,digest:sha256(body)});}}files.sort((a,b)=>a.path.localeCompare(b.path));
 const porcelain=execFileSync('git',['status','--porcelain=v1','--',...PROTECTED_ROOTS.map(root=>`platform/${root}`)],{cwd:ROOT,encoding:'utf8'});
 const historicalAnchorAvailable=false;
 const value={schemaVersion:'1',kind:'protected-path-manifest',phase,head:SOURCE_REVISION,capturedAt:new Date().toISOString(),dirtyState:porcelain.trim().length>0,worktreeStatusDigest:sha256(porcelain),roots:PROTECTED_ROOTS,files,treeDigest:sha256(files),provenance:{immutable:phase==='before',historicalAnchorAvailable,status:phase==='before'?'BLOCKED':'CURRENT',reason:phase==='before'?'PRE_WORKLOAD_SNAPSHOT_NOT_AVAILABLE_AFTER_IMPLEMENTATION':'POST_WORKLOAD_SNAPSHOT'}};
 return writeJson(target,value);
}
export function diffProtectedManifests(before,after){const left=new Map(before.files.map((file)=>[file.path,file.digest])),right=new Map(after.files.map((file)=>[file.path,file.digest]));const changed=[...new Set([...left.keys(),...right.keys()])].filter((path)=>left.get(path)!==right.get(path)).sort();const removed=changed.filter((path)=>left.has(path)&&!right.has(path)),added=changed.filter((path)=>!left.has(path)&&right.has(path));const renames=[];for(const from of removed)for(const to of added)if(left.get(from)===right.get(to))renames.push({from,to,digest:left.get(from)});return{changed,renames};}
export async function compareProtected(){const before=await readJson(join(EVIDENCE,'workload-protected.before.json'));const after=await readJson(join(EVIDENCE,'workload-protected.after.json'));const {changed,renames}=diffProtectedManifests(before,after);const anchored=before.provenance?.historicalAnchorAvailable===true&&before.provenance?.immutable===true;const status=!anchored?'BLOCKED':changed.length===0?'PASS':'FAIL';return artifact(join(EVIDENCE,'workload-protected.diff.json'),{schemaVersion:'1',caseId:'apgv/workload/v1/protected-diff',status,changed,renames,beforeDigest:before.treeDigest,afterDigest:after.treeDigest,protectedFileCount:after.files.length,observedAt:new Date().toISOString(),sourceDigest:sha256([before.treeDigest,after.treeDigest]),toolDigest:sha256('agent-platform-final/protected-manifest@2'),reason:anchored?undefined:'PRE_WORKLOAD_SNAPSHOT_NOT_AVAILABLE_AFTER_IMPLEMENTATION'});}

