export async function buildPreflight(){const inputs=await dependencyInputs();const dependencies=[];for(const input of inputs.dependencies){const progress=await taskProgress(input);const evidencePath=join(PLATFORM,input.evidence);const evidenceDigest=await exists(evidencePath)?sha256(await readFile(evidencePath)):null;let strictValidation='FAIL';try{execFileSync('openspec',['validate',input.change,'--strict'],{cwd:ROOT,stdio:'pipe'});strictValidation='PASS';}catch{/* fail closed */}const production=input.change==='agent-platform-production-governance';const readiness=production&&evidenceDigest?await readJson(evidencePath):undefined;const complete=progress.total>0&&progress.remaining===0;const repositoryInputConsumable=evidenceDigest!==null&&strictValidation==='PASS'&&complete&&(!production||readiness.productionEvidence===false);const status=production?'BLOCKED':repositoryInputConsumable?'PASS':'BLOCKED';dependencies.push({...input,progress,planningArtifacts:'PRESENT',strictValidation,evidenceDigest,repositoryInputConsumable,status,reason:production?'EXTERNAL_PRODUCTION_EVIDENCE_AND_APPROVALS_REQUIRED':!complete?'DEPENDENCY_TASKS_INCOMPLETE':strictValidation!=='PASS'?'STRICT_VALIDATION_FAILED':evidenceDigest===null?'EVIDENCE_MISSING':'REPOSITORY_BASELINE_CONSUMABLE'});}const blocked=dependencies.some((item)=>item.status!=='PASS');return artifact(join(EVIDENCE,'entry-preflight.json'),{schemaVersion:'1',caseId:'apgv/entry/v1/dependency-preflight',status:blocked?'BLOCKED':'PASS',decision:blocked?'NO-GO':'GO',sourceRevision:SOURCE_REVISION,sourceDigest:sha256(dependencies.map(({change,evidenceDigest,strictValidation,progress})=>({change,evidenceDigest,strictValidation,progress}))),toolDigest:sha256(execFileSync('openspec',['--version'],{cwd:ROOT,encoding:'utf8'})),checkedAt:new Date().toISOString(),dependencies,externalDeferredTaskIds:inputs.externalDeferredTaskIds,promotionStarted:false});}
export async function buildEntryManifest(){const inputs=await dependencyInputs(),preflight=await readJson(join(EVIDENCE,'entry-preflight.json'));const dependencies=preflight.dependencies.map((item)=>({change:item.change,owner:item.owner,status:item.status,evidenceRef:relative(PLATFORM,join(PLATFORM,item.evidence)),evidenceDigest:item.evidenceDigest}));return artifact(join(EVIDENCE,'entry-manifest.json'),{schemaVersion:'1',caseId:'apgv/entry/v1/dependency-manifest',status:preflight.status,decision:preflight.decision,canonicalContractMajor:inputs.canonicalContractMajor,sourceRevision:SOURCE_REVISION,sourceDigest:preflight.sourceDigest,toolDigest:preflight.toolDigest,compatibilityWindow:inputs.compatibilityWindow,productionFreshnessHours:inputs.productionFreshnessHours,dependencies,externalDeferredTaskIds:inputs.externalDeferredTaskIds,promotionToken:null,generatedAt:new Date().toISOString()});}

