 await localReport('engine-comparison.json',{...metadata,pairCount:engineCases.length,referenceBuild:sha256('deterministic-reference@1'),piBuild:sha256('pi@0.73.1'),allowedNonExact:['text','reasoning','internal-turn'],forbiddenCanonical:['outcome','error','authority','receipt','artifact','checkpoint','budget'],canonicalDifferences:[],nonExactReasons:['engine-private-text-omitted'],cases:engineCases.map(({caseId,status})=>({caseId,status}))},raw.engine.status);
