 for(const fact of ['release-spec','lifecycle','admission-spec','effect','usage','artifact','checkpoint','secret','projection'])if(!facts.has(fact))errors.push(`REQUIRED_AUTHORITY_MISSING:${fact}`);
 const boundaryIds=new Set();for(const boundary of model.trustBoundaries??[]){if(boundaryIds.has(boundary.id))errors.push(`DUPLICATE_TRUST_BOUNDARY:${boundary.id}`);boundaryIds.add(boundary.id);if(!['defined','uncertain'].includes(boundary.status))errors.push(`TRUST_BOUNDARY_STATUS_INVALID:${boundary.id}`);for(const member of boundary.members??[])if(!ids.has(member))errors.push(`TRUST_BOUNDARY_MEMBER_MISSING:${boundary.id}:${member}`);}
 for(const recovery of model.recovery??[]){if(!idPattern.test(recovery.id)||!ids.has(recovery.source))errors.push(`RECOVERY_SOURCE_INVALID:${recovery.id}`);if(!recovery.owner||!recovery.action)errors.push(`RECOVERY_METADATA_INCOMPLETE:${recovery.id}`);}
