export async function buildBundle(){const bundle=join(EVIDENCE,'bundle');await mkdir(bundle,{recursive:true});const evidenceFiles=(await walk(EVIDENCE)).filter(path=>!path.startsWith(`${bundle}/`)&&!path.endsWith('.tsbuildinfo'));const schemaFiles=await walk(join(PLATFORM,'scripts/agent-platform-final/schemas'));const sources=[join(DESIGN,'generic-agent-platform-final.md'),join(DESIGN,'generic-agent-platform-final.system-model.json'),join(DESIGN,'generic-agent-platform-final.runtime.dsl.yaml'),join(DESIGN,'generic-agent-platform-final.runtime.md'),join(DESIGN,'generic-agent-platform-final.runtime.render.normalized.json'),join(DESIGN,'generic-agent-platform-final.architecture-review.yaml'),join(PLATFORM,'scripts/agent-platform-final/lib.mjs'),join(PLATFORM,'package.json'),join(PLATFORM,'pnpm-lock.yaml'),...schemaFiles,...evidenceFiles];const unique=[...new Set(sources)];const entries=[];for(const source of unique){const name=relative(ROOT,source).replaceAll('/','__');const target=join(bundle,name);await cp(source,target);entries.push({path:name,digest:sha256(await readFile(target)),source:relative(ROOT,source)});}const verifier=`import{createHash}from'node:crypto';import{readFile}from'node:fs/promises';const canonical=v=>JSON.stringify(sort(v));const sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,c])=>[k,sort(c)])):v;const sha=v=>'sha256:'+createHash('sha256').update(typeof v==='string'||Buffer.isBuffer(v)?v:canonical(v)).digest('hex');const index=JSON.parse(await readFile(new URL('./bundle-index.json',import.meta.url)));const mismatch=[];const bySource=new Map(index.entries.map(e=>[e.source,e]));for(const e of index.entries){try{if(sha(await readFile(new URL('./'+e.path,import.meta.url)))!==e.digest)mismatch.push(e.source)}catch{mismatch.push(e.source)}}const load=async source=>JSON.parse(await readFile(new URL('./'+bySource.get(source).path,import.meta.url)));const model=await load('docs/design/_cross/generic-agent-platform-final.system-model.json'),dsl=await load('docs/design/_cross/generic-agent-platform-final.runtime.dsl.yaml'),render=await load('docs/design/_cross/generic-agent-platform-final.runtime.render.normalized.json'),review=await load('docs/design/_cross/generic-agent-platform-final.architecture-review.yaml'),gate=await load('platform/evidence/agent-platform-final/gate-manifest.json'),executed=await load('platform/evidence/agent-platform-final/executed-results.json');if(dsl.modelDigest!==sha(model))mismatch.push('dsl:modelDigest');if(render.sourceDslDigest!==dsl.contentDigest)mismatch.push('render:dslDigest');if(review.modelDigest!==sha(model))mismatch.push('review:modelDigest');if(gate.sourceDigest!==executed.sourceDigest)mismatch.push('gate:sourceDigest');if(gate.status!=='BLOCKED'||gate.decision!=='NO-GO')mismatch.push('gate:decision');console.log(JSON.stringify({status:mismatch.length?'FAIL':'PASS',mismatches:mismatch,entryCount:index.entries.length,networkUsed:false,workspaceCacheUsed:false}));if(mismatch.length)process.exitCode=1;`;const verifierPath=join(bundle,'offline-verify.mjs');await writeFile(verifierPath,verifier);entries.push({path:'offline-verify.mjs',digest:sha256(await readFile(verifierPath)),source:'bundle/offline-verify.mjs'});const base={schemaVersion:'1',sourceRevision:SOURCE_REVISION,sourceDigest:(await readJson(join(EVIDENCE,'executed-results.json'))).sourceDigest,toolDigest:sha256(await readFile(join(PLATFORM,'scripts/agent-platform-final/lib.mjs'))),generatedAt:new Date().toISOString(),entryCount:entries.length,entries,decision:'NO-GO',status:'BLOCKED',verifyCommand:'node offline-verify.mjs'};return artifact(join(bundle,'bundle-index.json'),base);}
export async function verifyArchive(bundle=join(EVIDENCE,'bundle')){const index=await readJson(join(bundle,'bundle-index.json'));if(!verifyContentDigest(index))throw new Error('BUNDLE_INDEX_DIGEST_INVALID');let parsed;try{parsed=JSON.parse(execFileSync(process.execPath,[join(bundle,'offline-verify.mjs')],{cwd:bundle,encoding:'utf8'}));}catch(error){parsed={status:'FAIL',mismatches:['OFFLINE_VERIFIER_FAILED'],detail:error instanceof Error?error.message:String(error)};}const result=await localReport('reproducibility.json',{caseId:'apgv/archive/v1/offline-verification',bundleDigest:index.contentDigest,entryCount:index.entries.length,mismatches:parsed.mismatches??[],networkUsed:parsed.networkUsed??false,workspaceCacheUsed:parsed.workspaceCacheUsed??false,isolatedVerifier:'bundle/offline-verify.mjs'},parsed.status==='PASS'?'PASS':'FAIL');return result;}
